36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    @Column(name = "registration_date")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "birth_date")
64	    private LocalDate birthDate;
65	
66	    @Column(name = "customer_code")
67	    private String customerCode;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Column(name = "membership_number")
76	    private String membershipNumber;
77	
78	    @Column(name = "bulk_signup_warning")
79	    private Boolean bulkSignupWarning;
80	
81	    @Column(name = "household_size")
82	    private Integer householdSize;
83	
84	    @Column(name = "possible_duplicate")
85	    private Boolean possibleDuplicate;
86	
87	    @Column(name = "possible_duplicate_of")
88	    private Integer possibleDuplicateOf;
89	
90	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
91	    private Set<Pet> pets;
92	
93	    public String getAddress() {
94	        return this.address;
95	    }
96	
97	    public void setAddress(String address) {
98	        this.address = address;
99	    }
100	
101	    public String getCity() {
102	        return this.city;
103	    }
104	
105	    public void setCity(String city) {
106	        this.city = city;
107	    }
108	
109	    /**
110	     * The owner's locality, i.e. the canonical region it belongs to (read from the
111	     * assigned {@link #customerCode} when present, otherwise derived from the owner's
112	     * own fields via {@link #regionForOwner()}). Derived (not persisted); recomputed
113	     * each call. See {@link OwnerDerivations#locality(String, String, String)} for the
114	     * full derivation.
115	     *
116	     * @return the canonical region string, or {@code "UNKNOWN"}
117	     */
118	    @Transient
119	    public String getLocality() {
120	        return OwnerDerivations.locality(this.customerCode, this.postcode, this.city);
121	    }
122	
123	    /**
124	     * The canonical region derived for this owner from its own fields. Recomputed each
125	     * call. See {@link OwnerDerivations#region(String, String)} for the derivation.
126	     *
127	     * @return the canonical region string, or {@code "UNKNOWN"}
128	     */
129	    public String regionForOwner() {
130	        return OwnerDerivations.region(this.postcode, this.city);
131	    }
132	
133	    /**
134	     * Whether this owner's postcode is consistent with its {@link #getLocality()
135	     * locality}: an absent postcode is accepted, a present one must be exactly four
136	     * digits and, when the locality has a known postcode range, fall within it. See
137	     * {@link OwnerDerivations#postcodeMatchesRegion(String, String)}.
138	     *
139	     * @return {@code true} if the postcode is absent or valid for the owner's locality
140	     */
141	    public boolean postcodeValidForLocality() {
142	        return OwnerDerivations.postcodeMatchesRegion(this.postcode, this.getLocality());
143	    }
144	
145	    /**
146	     * The owner's membership level, a number from 1 to 3. Derived (not persisted);
147	     * recomputed from the current fields each call. See
148	     * {@link OwnerDerivations#membershipLevel(String, Integer)} for how it is assigned.
149	     *
150	     * @return the membership level, from 1 to 3
151	     */
152	    @Transient
153	    public Integer getMembershipLevel() {
154	        return OwnerDerivations.membershipLevel(this.email, this.namesakeCount);
155	    }
156	
157	    /**
158	     * The owner's preferred contact channel, {@code "EMAIL"} or {@code "PHONE"}.
159	     * Derived (not persisted); recomputed from the current fields each call. See
160	     * {@link OwnerDerivations#contactPreference(String)}.
161	     *
162	     * @return {@code "EMAIL"} or {@code "PHONE"}
163	     */
164	    @Transient
165	    public String getContactPreference() {
166	        return OwnerDerivations.contactPreference(this.email);
167	    }
168	
169	    public String getTelephone() {
170	        return this.telephone;
171	    }
172	
173	    public void setTelephone(String telephone) {
174	        this.telephone = telephone;
175	    }
176	
177	    public String getEmail() {
178	        return this.email;
179	    }
180	
181	    public void setEmail(String email) {
182	        this.email = email;
183	    }
184	
185	    public String getPostcode() {
186	        return this.postcode;
187	    }
188	
189	    public void setPostcode(String postcode) {
190	        this.postcode = postcode;
191	    }
192	
193	    public LocalDate getRegistrationDate() {
194	        return this.registrationDate;
195	    }
196	
197	    public void setRegistrationDate(LocalDate registrationDate) {
198	        this.registrationDate = registrationDate;
199	    }
200	
201	    public LocalDate getBirthDate() {
202	        return this.birthDate;
203	    }
204	
205	    public void setBirthDate(LocalDate birthDate) {
206	        this.birthDate = birthDate;
207	    }
208	
209	    /**
210	     * The owner's age band, {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"},
211	     * derived from {@link #birthDate} measured against {@link #registrationDate}.
212	     * Derived (not persisted); recomputed each call and {@code null} when no birth
213	     * date has been supplied. See
214	     * {@link OwnerDerivations#ageBand(LocalDate, LocalDate)} for the derivation.
215	     *
216	     * @return the age band, or {@code null} when no birth date is present
217	     */
218	    @Transient
219	    public String getAgeBand() {
220	        return OwnerDerivations.ageBand(this.birthDate, this.registrationDate);
221	    }
222	
223	    public String getCustomerCode() {
224	        return this.customerCode;
225	    }
226	
227	    public void setCustomerCode(String customerCode) {
228	        this.customerCode = customerCode;
229	    }
230	
231	    /**
232	     * The Luhn check digit (0-9) computed over the digits in this owner's
233	     * {@link #customerCode}. Derived (not persisted); recomputed each call. See
234	     * {@link OwnerDerivations#checkDigit(String)}.
235	     *
236	     * @return the Luhn check digit, from 0 to 9
237	     */
238	    @Transient
239	    public Integer getCheckDigit() {
240	        return OwnerDerivations.checkDigit(this.customerCode);
241	    }
242	
243	    public String getHouseholdId() {
244	        return this.householdId;
245	    }
246	
247	    public void setHouseholdId(String householdId) {
248	        this.householdId = householdId;
249	    }
250	
251	    public Integer getNamesakeCount() {
252	        return this.namesakeCount;
253	    }
254	
255	    public void setNamesakeCount(Integer namesakeCount) {
256	        this.namesakeCount = namesakeCount;
257	    }
258	
259	    public String getMembershipNumber() {
260	        return this.membershipNumber;
261	    }
262	
263	    public void setMembershipNumber(String membershipNumber) {
264	        this.membershipNumber = membershipNumber;
265	    }
266	
267	    public Boolean getBulkSignupWarning() {
268	        return this.bulkSignupWarning;
269	    }
270	
271	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
272	        this.bulkSignupWarning = bulkSignupWarning;
273	    }
274	
275	    public Integer getHouseholdSize() {
276	        return this.householdSize;
277	    }
278	
279	    public void setHouseholdSize(Integer householdSize) {
280	        this.householdSize = householdSize;
281	    }
282	
283	    public Boolean getPossibleDuplicate() {
284	        return this.possibleDuplicate;
285	    }
286	
287	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
288	        this.possibleDuplicate = possibleDuplicate;
289	    }
290	
291	    public Integer getPossibleDuplicateOf() {
292	        return this.possibleDuplicateOf;
293	    }
294	
295	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
296	        this.possibleDuplicateOf = possibleDuplicateOf;
297	    }
298	
299	    /**
300	     * The derived key used for duplicate detection, combining this owner's normalised
301	     * telephone, email and {@link #householdId}. Two owners are duplicates exactly when
302	     * their whole identity keys are equal, so members of the same household with
303	     * different telephones have different keys. Derived (not persisted); recomputed each
304	     * call. See {@link OwnerDerivations#identityKey(String, String, String)} for the
305	     * exact format.
306	     *
307	     * @return the owner's identity key
308	     */
309	    @Transient
310	    public String getIdentityKey() {
311	        return OwnerDerivations.identityKey(this.telephone, this.email, this.householdId);
312	    }
313	
314	    /**
315	     * Compute the customer code to assign to this owner at creation, formatted
316	     * {@code <REGION>-<HASH8>} from the owner's (already normalised) fields. This is the
317	     * value stored in {@link #getCustomerCode()}; see
318	     * {@link OwnerDerivations#customerCode(String, String, String)} for the format.
319	     *
320	     * @return the customer code to assign
321	     */
322	    public String computeCustomerCode() {
323	        return OwnerDerivations.customerCode(regionForOwner(), this.telephone, this.getLastName());
324	    }
325	
326	    /**
327	     * Compute the stable household identifier for this owner, derived deterministically
328	     * from its last name and postcode so every owner sharing a last name and postcode
329	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
330	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
331	     *
332	     * @return the household identifier
333	     */
334	    public String computeHouseholdId() {
335	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
336	    }
337	
338	    /**
339	     * Whether this owner belongs to the same household as {@code other}: that is, they
340	     * share the same last name and postcode. The last name is compared
341	     * case-insensitively with runs of whitespace collapsed to a single space (and
342	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
343	     * absent postcodes count as equal). Owners in the same household resolve to the same
344	     * {@link #computeHouseholdId() household identifier}.
345	     *
346	     * @param other the owner to compare against
347	     * @return {@code true} if both owners share a household
348	     */
349	    public boolean sameHouseholdAs(Owner other) {
350	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
351	            && Objects.equals(this.postcode, other.postcode);
352	    }
353	
354	    /**
355	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
356	     * trim, collapse internal runs of whitespace to a single space and lower-case.
357	     */
358	    private static String normalize(String value) {
359	        if (value == null) {
360	            return "";
361	        }
362	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
363	    }
364	
365	    /**
366	     * Reduce an address to its canonical stored form: trim and collapse runs of
367	     * whitespace to a single space, upper-case, and expand common abbreviations
368	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
369	     * they appear as whole words. The result is what is stored, returned and used
370	     * for every household comparison; it is idempotent, so re-normalising an
371	     * already-normalised address leaves it unchanged.
372	     *
373	     * @param value the raw address (may be {@code null})
374	     * @return the normalised address, or the empty string if {@code value} is
375	     *         {@code null} or blank
376	     */
377	    public static String normalizeAddress(String value) {
378	        if (value == null) {
379	            return "";
380	        }
381	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
382	        if (collapsed.isEmpty()) {
383	            return "";
384	        }
385	        String[] tokens = collapsed.split(" ");
386	        for (int i = 0; i < tokens.length; i++) {
387	            tokens[i] = switch (tokens[i]) {
388	                case "ST" -> "STREET";
389	                case "RD" -> "ROAD";
390	                case "AVE" -> "AVENUE";
391	                default -> tokens[i];
392	            };
393	        }
394	        return String.join(" ", tokens);
395	    }
396	
397	    protected Set<Pet> getPetsInternal() {
398	        if (this.pets == null) {
399	            this.pets = new HashSet<>();
400	        }
401	        return this.pets;
402	    }
403	
404	    protected void setPetsInternal(Set<Pet> pets) {
405	        this.pets = pets;
406	    }
407	
408	    public List<Pet> getPets() {
409	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
410	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
411	        return Collections.unmodifiableList(sortedPets);
412	    }
413	
414	    public void setPets(List<Pet> pets) {
415	        this.pets = new HashSet<>(pets);
416	    }
417	
418	    public void addPet(Pet pet) {
419	        getPetsInternal().add(pet);
420	        pet.setOwner(this);
421	    }
422	
423	    /**
424	     * Return the Pet with the given name, or null if none found for this Owner.
425	     *
426	     * @param name to test
427	     * @return true if pet name is already in use
428	     */
429	    public Pet getPet(String name) {
430	        return getPet(name, false);
431	    }
432	
433	    /**
434	     * Return the Pet with the given name, or null if none found for this Owner.
435	     *
436	     * @param name to test
437	     * @return true if pet name is already in use
438	     */
439	    public Pet getPet(String name, boolean ignoreNew) {
440	        name = name.toLowerCase();
441	        for (Pet pet : getPetsInternal()) {
442	            if (!ignoreNew || !pet.isNew()) {
443	                String compName = pet.getName();
444	                compName = compName.toLowerCase();
445	                if (compName.equals(name)) {
446	                    return pet;
447	                }
448	            }
449	        }
450	        return null;
451	    }
452	
453	    public Pet getPet(Integer petId) {
454	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
455	    }
456	
457	    @Override
458	    public String toString() {
459	        return new ToStringCreator(this)
460	
461	            .append("id", this.getId())
462	            .append("new", this.isNew())
463	            .append("lastName", this.getLastName())
464	            .append("firstName", this.getFirstName())
465	            .append("address", this.address)
466	            .append("city", this.city)
467	            .append("telephone", this.telephone)
468	            .toString();
469	    }
470	}
